/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int data;
 *     TreeNode *left;
 *     TreeNode *right;
 *      TreeNode(int val) : data(val) , left(nullptr) , right(nullptr) {}
 * };
 **/

class Solution{
    public:
    void traverse(TreeNode *root, map<int, pair<int,int>> &nodeMap, int row, int col){
        if(root == nullptr) return;

        if(nodeMap.find(col) != nodeMap.end()){
            if(nodeMap[col].first > row) nodeMap[col] = {row, root -> data};
        }
        else nodeMap[col] = {row, root -> data};

        traverse(root -> left, nodeMap, row+1, col-1);
        traverse(root -> right, nodeMap, row+1, col+1);

    }
    vector<int> topView(TreeNode *root){
        map<int, pair<int,int>> nodeMap;     // col, {row, num}
        traverse(root, nodeMap, 0, 0);
        vector<int> ans;
        for(auto it: nodeMap){
            ans.push_back(it.second.second);
        }
        return ans;
    }
};
```

