/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int data;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int val) { data = val; left = null, right = null }
 * }
 **/
class Q {
    TreeNode root;
    int c;
    public Q(TreeNode root, int c) {
        this.root = root;
        this.c = c;
    }
}
class Solution {
    void leverOrderTraversal(Queue<Q> q, List<Integer> ls) {
        Map<Integer, Integer> map = new HashMap<>();
        int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
        while(!q.isEmpty()) {
            Q tQ = q.remove();
            if(map.get(tQ.c)==null) {
                map.put(tQ.c,tQ.root.data);
                if(min > tQ.c ) min = tQ.c;      
                if(max < tQ.c) max = tQ.c;
            }
            if(tQ.root.left!=null) 
                 q.add(new Q(tQ.root.left, tQ.c-1));
            if(tQ.root.right!=null) 
                 q.add(new Q(tQ.root.right, tQ.c+1));
        }
        System.out.println(min+" "+max);
        for(int i = min; i<=max; i++)
            ls.add(map.get(i));
    }
    public List<Integer> topView(TreeNode root) {
        List<Integer> ls = new ArrayList<>();
        if(root == null) return ls; 
        Queue<Q> q = new LinkedList<>();
        q.add(new Q(root,0));
        leverOrderTraversal(q, ls);
        return ls;
    }   
}
